# Bug fix

## error stack
call `tls_process_server_hello(ssl/statem/statem_clnt.c:1400)` to process server hello 
call `set_client_ciphersuite(ssl/statem/statem_clnt.c:1653)` to set ciphersuite
call `ssl_get_ciphers_by_id(ssl/statem/statem_clnt.c:1348)` to collect ciphers **(This is BUG)**
```
sk = ssl_get_ciphers_by_id(s);
```
call `sk_SSL_CIPHER_find(ssl/statem/statem_clnt.c:1348)` to find cipher, but sk num is 0, so can not find any cipher
```
i = sk_SSL_CIPHER_find(sk, c);
```
so return error `(ssl/statem/statem_clnt.c:1353)`
```
        SSLfatal(s, SSL_AD_ILLEGAL_PARAMETER, SSL_F_SET_CLIENT_CIPHERSUITE,
                 SSL_R_WRONG_CIPHER_RETURNED);
```

## error reason
when OpenSSL use any API to call `update_cipher_list_by_id(ssl/ssl_ciph.c:1325)`, will call sk_SSL_CIPHER_dup(`ssl/ssl_ciph.c:1328`) to dup ciphers, but sk_SSL_CIPHER_dup is not work exactly in AIX5.3
```
static int update_cipher_list_by_id(STACK_OF(SSL_CIPHER) **cipher_list_by_id,
                                    STACK_OF(SSL_CIPHER) *cipherstack)
{
    STACK_OF(SSL_CIPHER) *tmp_cipher_list = sk_SSL_CIPHER_dup(cipherstack);

    if (tmp_cipher_list == NULL) {
        return 0;
    }

    sk_SSL_CIPHER_free(*cipher_list_by_id);
    *cipher_list_by_id = tmp_cipher_list;

    (void)sk_SSL_CIPHER_set_cmp_func(*cipher_list_by_id, ssl_cipher_ptr_id_cmp);
    sk_SSL_CIPHER_sort(*cipher_list_by_id);

    return 1;
}
```

## bug fix
all STACK_OF(*) struct is call OPENSSL_sk_dup(crypto/stack/stack.c:45)
```
OPENSSL_STACK *OPENSSL_sk_dup(const OPENSSL_STACK *sk)
{
    OPENSSL_STACK *ret;

    if ((ret = OPENSSL_malloc(sizeof(*ret))) == NULL) {
        CRYPTOerr(CRYPTO_F_OPENSSL_SK_DUP, ERR_R_MALLOC_FAILURE);
        return NULL;
    }

    /* direct structure assignment */
    *ret = *sk;

    if (sk->num == 0) {
        /* postpone |ret->data| allocation */
        ret->data = NULL;
        ret->num_alloc = 0;
        return ret;
    }
    /* duplicate |sk->data| content */
    if ((ret->data = OPENSSL_malloc(sizeof(*ret->data) * sk->num_alloc)) == NULL)
        goto err;
    memcpy(ret->data, sk->data, sizeof(void *) * sk->num);
    return ret;
 err:
    OPENSSL_sk_free(ret);
    return NULL;
}
```
direct structure assignment can not work exactly, so modify code `*ret = *sk;` to `memcpy(ret, sk, sizeof(OPENSSL_STACK));` will resolve this problem


## Full fix code

function is `OPENSSL_sk_dup` and `OPENSSL_sk_deep_copy` in `crypto/stack/stack.c`

```

OPENSSL_STACK *OPENSSL_sk_dup(const OPENSSL_STACK *sk)
{
    OPENSSL_STACK *ret;

    if ((ret = OPENSSL_malloc(sizeof(*ret))) == NULL) {
        CRYPTOerr(CRYPTO_F_OPENSSL_SK_DUP, ERR_R_MALLOC_FAILURE);
        return NULL;
    }

    /*
     * Fix direct structure assignment not work, see:
     * https://github.com/openssl/openssl/issues/19074
     */
    memcpy(ret, sk, sizeof(OPENSSL_STACK));

    if (sk->num == 0) {
        /* postpone |ret->data| allocation */
        ret->data = NULL;
        ret->num_alloc = 0;
        return ret;
    }
    /* duplicate |sk->data| content */
    if ((ret->data = OPENSSL_malloc(sizeof(*ret->data) * sk->num_alloc)) == NULL)
        goto err;
    memcpy(ret->data, sk->data, sizeof(void *) * sk->num);
    return ret;
 err:
    OPENSSL_sk_free(ret);
    return NULL;
}

OPENSSL_STACK *OPENSSL_sk_deep_copy(const OPENSSL_STACK *sk,
                             OPENSSL_sk_copyfunc copy_func,
                             OPENSSL_sk_freefunc free_func)
{
    OPENSSL_STACK *ret;
    int i;

    if ((ret = OPENSSL_malloc(sizeof(*ret))) == NULL) {
        CRYPTOerr(CRYPTO_F_OPENSSL_SK_DEEP_COPY, ERR_R_MALLOC_FAILURE);
        return NULL;
    }

    /*
     * Fix direct structure assignment not work, see:
     * https://github.com/openssl/openssl/issues/19074
     */
    memcpy(ret, sk, sizeof(OPENSSL_STACK));

    if (sk->num == 0) {
        /* postpone |ret| data allocation */
        ret->data = NULL;
        ret->num_alloc = 0;
        return ret;
    }

    ret->num_alloc = sk->num > min_nodes ? sk->num : min_nodes;
    ret->data = OPENSSL_zalloc(sizeof(*ret->data) * ret->num_alloc);
    if (ret->data == NULL) {
        OPENSSL_free(ret);
        return NULL;
    }

    for (i = 0; i < ret->num; ++i) {
        if (sk->data[i] == NULL)
            continue;
        if ((ret->data[i] = copy_func(sk->data[i])) == NULL) {
            while (--i >= 0)
                if (ret->data[i] != NULL)
                    free_func((void *)ret->data[i]);
            OPENSSL_sk_free(ret);
            return NULL;
        }
    }
    return ret;
}
```
